        //
        // So we can binary search on X. For each X, build the subgraph of nodes with a[i] >= X, find the largest connected component, and check if its size >= k.
        //
        // But n is up to 200,000, and binary search would be O(log(max_a)) * O(n) which is about 20 * 200000 = 4e6, which is acceptable.

        int low = 1;
