        // So answer is 1. Correct.

        // Great, so the solution is binary search on X, and for each X, check if the subgraph induced by nodes with a[i] >= X has a connected component of size >= k.

        long low = 1, high = 1000000;
        int ans = 1;
        while (low <= high) {
            long mid = (low + high) / 2;
            if (check(n, k, a, adj, mid)) {
                ans = (int) mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        System.out.println(ans);
    }

    static boolean check(int n, int k, int[] a, List<List<Integer>> adj, long X) {
        boolean[] active = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            active[i] = a[i] >= X;
        }

        boolean[] visited = new boolean[n + 1];
        int[] queue = new int[n];

        for (int i = 1; i <= n; i++) {
            if (active[i] && !visited[i]) {
                // BFS to find component size
                int head = 0, tail = 0;
                queue[tail++] = i;
                visited[i] = true;
                int size = 0;
                while (head < tail) {
                    int u = queue[head++];
                    size++;
                    for (int v : adj.get(u)) {
                        if (active[v] && !visited[v]) {
                            visited[v] = true;
                            queue[tail++] = v;
                        }
                    }
                }
                if (size >= k) {
                    return true;
                }
            }
        }
        return false;
    }
