        // Total time: O(n * log(max(a))) which is fine for n = 200,000.

        int low = 1;
        int high = 0;
        for (int i = 1; i <= n; i++) {
            high = Math.max(high, a[i]);
        }

        int ans = 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (check(n, k, a, adj, mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        System.out.println(ans);
    }

    static boolean check(int n, int k, int[] a, List<List<Integer>> adj, int x) {
        boolean[] visited = new boolean[n + 1];
        boolean[] valid = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            valid[i] = a[i] >= x;
        }

        for (int i = 1; i <= n; i++) {
            if (!visited[i] && valid[i]) {
                // BFS/DFS to find the size of the connected component
                int count = 0;
                Deque<Integer> queue = new ArrayDeque<>();
                queue.add(i);
                visited[i] = true;
                while (!queue.isEmpty()) {
                    int u = queue.poll();
                    count++;
                    for (int v : adj.get(u)) {
                        if (!visited[v] && valid[v]) {
                            visited[v] = true;
                            queue.add(v);
                        }
                    }
                }
                if (count >= k) {
                    return true;
                }
            }
        }
        return false;
    }
